    if (d < ds[0]) return D.coef.rN;                // before the new-moon evening: not visible
    if (d > ds[ds.length - 1]) return D.coef.rA;    // after the last map: easily visible
    var best = ds[0];                               // gap in a partial table: nearest measured evening
