    if (steps.length) {
      var at = null, bv = -1;
      steps[steps.length - 1].vit.forEach(function (v, k) { if (v[0] > bv) { bv = v[0]; at = k; } });
      for (var i = steps.length - 1; i >= 0; i--) { path[i] = at; at = steps[i].vit.get(at)[1]; }
    }

